#!/usr/bin/env bash
# Renders installer/install.sh.tmpl into a standalone install.sh: the brand
# values from installer/brand.env (generated by brandgen) and the release
# version are pasted in, so `curl ... | sh` needs no other file.
#
# Usage: scripts/render-installer.sh [version] [output]
#   version defaults to "latest", output to installer/install.sh
#
# Test builds only: INSTALLER_TEST_PUBLIC_KEY=<RW... minisign key> renders an
# installer that trusts that key instead of brand.minisignPublicKey (the e2e
# signs its releases with a throwaway key). The installer then warns
# "TEST BUILD" on every run. Release builds never set it.
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
version="${1:-latest}"
version="${version#v}"
out="${2:-$root/installer/install.sh}"
tmpl="$root/installer/install.sh.tmpl"
env_file="$root/installer/brand.env"

case "$version" in
latest | [0-9]*) ;;
*) echo "render-installer: bad version '$version'" >&2; exit 2 ;;
esac
test_key="${INSTALLER_TEST_PUBLIC_KEY:-}"
if [ -n "$test_key" ] && ! [[ "$test_key" =~ ^RW[A-Za-z0-9+/]{54}$ ]]; then
  echo "render-installer: INSTALLER_TEST_PUBLIC_KEY is not a minisign public key (RW...)" >&2
  exit 2
fi

# The Docker versions the node health check enforces, so the installer and
# nodecheck never disagree (go/internal/nodecheck/checks.go).
checks="$root/go/internal/nodecheck/checks.go"
docker_const() { sed -n "s/^[[:space:]]*$1[[:space:]]*=[[:space:]]*\([0-9][0-9]*\).*/\1/p" "$checks" | head -1; }
docker_min=$(docker_const minDockerMajor)
docker_rec=$(docker_const recommendedDockerMajor)
if [ -z "$docker_min" ] || [ -z "$docker_rec" ]; then
  echo "render-installer: no minDockerMajor/recommendedDockerMajor constants in $checks" >&2
  exit 1
fi
# The panel container's user, which the installer checks no account has
# (go/internal/docker/names.go PanelUID).
names="$root/go/internal/docker/names.go"
panel_uid=$(sed -n 's/^[[:space:]]*PanelUID[[:space:]]*=[[:space:]]*\([0-9][0-9]*\).*/\1/p' "$names" | head -1)
if [ -z "$panel_uid" ]; then
  echo "render-installer: no PanelUID constant in $names" >&2
  exit 1
fi
# The panel's reserved service id, whose containers the installer reads the
# running panel's version from (go/internal/docker/names.go PanelServiceID).
panel_service=$(sed -n 's/^[[:space:]]*PanelServiceID[[:space:]]*=[[:space:]]*"\([a-z0-9]*\)".*/\1/p' "$names" | head -1)
if [ -z "$panel_service" ]; then
  echo "render-installer: no PanelServiceID constant in $names" >&2
  exit 1
fi

brand=$(grep -v '^#' "$env_file")
tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT
while IFS= read -r line || [ -n "$line" ]; do
  case "$line" in
  '@@BRAND_ENV@@') printf '%s\n' "$brand" ;;
  *)
    line="${line//@@VERSION@@/$version}"
    line="${line//@@MIN_DOCKER_MAJOR@@/$docker_min}"
    line="${line//@@RECOMMENDED_DOCKER_MAJOR@@/$docker_rec}"
    line="${line//@@PANEL_UID@@/$panel_uid}"
    line="${line//@@PANEL_SERVICE_ID@@/$panel_service}"
    printf '%s\n' "${line//@@TEST_RELEASE_PUBLIC_KEY@@/$test_key}"
    ;;
  esac
done <"$tmpl" >"$tmp"
if grep -q '@@[A-Z_]*@@' "$tmp"; then
  echo "render-installer: unreplaced placeholder in $tmpl" >&2
  exit 1
fi
mkdir -p "$(dirname "$out")"
mv "$tmp" "$out"
chmod 0755 "$out"
trap - EXIT
echo "rendered $out ($version)"
